parameters.jsonBody:
={
  "contents": [
    {
      "parts": [
        {
          "text": "Bạn là biên tập viên kênh 'Nông nghiệp thông minh và tử tế' (tiếng Việt). Viết lại tin nông nghiệp công nghệ cao sau thành bài đăng Facebook tiếng Việt, văn phong đơn giản, gần gũi với nông dân Việt Nam (tránh thuật ngữ khó, nếu có thì giải thích ngay). Cấu trúc: 1 câu mở đầu gây tò mò, 3-5 câu tóm tắt mô hình/công nghệ, 1 đoạn 'Áp dụng ở Việt Nam thì sao?' (1-2 câu thực tế), kết thúc bằng 1 câu hỏi gợi thảo luận. Thêm 3-5 hashtag liên quan. Độ dài 120-180 từ.\n\nTiêu đề gốc: {{ $json.title }}\nNội dung gốc: {{ $json.contentSnippet }}\nLink gốc: {{ $json.link }}\\n\\nTrả về DUY NHẤT JSON hợp lệ, không có markdown fence, theo schema: {\"title\": string, \"body\": string, \"pillar\": \"mo_hinh_thuc_te\"|\"kien_thuc_khoa_hoc\"|\"meo_ap_dung_ngay\", \"claims\": [{\"text\": string, \"source\": string}], \"uncertainties\": [string], \"safety_note\": string, \"hashtags\": [string], \"source_url\": string}. Không bịa số liệu; nếu không có nguồn cho một claim thì đưa claim đó vào uncertainties và không trình bày như sự thật.\\n\\nTiêu đề gốc: {{ $json.title }}\\nNội dung gốc: {{ $json.contentSnippet }}\\nLink gốc: {{ $json.link }}"
        }
      ]
    }
  ],
  "generationConfig": {
    "responseMimeType": "application/json"
  }
}

parameters.text:
=🌱 Có bài mới cần duyệt cho kênh NNTT:

{{$json.title}}

{{$json.body}}

Trụ cột: {{$json.pillar}}
Nguồn: {{$json.source_url}}

Reviewer ghi approved_at/approved_by trong state staging trước khi bật luồng publish.

parameters.jsCode:
const raw = $json.candidates?.[0]?.content?.parts?.[0]?.text ?? $json.text ?? '';
let draft;
try { draft = typeof raw === 'string' ? JSON.parse(raw) : raw; }
catch (error) { throw new Error(`Gemini trả về JSON không hợp lệ: ${error.message}`); }
const required = ['title', 'body', 'pillar', 'claims', 'uncertainties', 'safety_note', 'hashtags', 'source_url'];
const missing = required.filter((key) => draft[key] === undefined || draft[key] === null);
if (missing.length) throw new Error(`Thiếu trường bắt buộc: ${missing.join(', ')}`);
const pillars = ['mo_hinh_thuc_te', 'kien_thuc_khoa_hoc', 'meo_ap_dung_ngay'];
if (!pillars.includes(draft.pillar)) throw new Error(`Trụ cột không hợp lệ: ${draft.pillar}`);
if (!Array.isArray(draft.claims) || !Array.isArray(draft.uncertainties) || !Array.isArray(draft.hashtags)) {
  throw new Error('claims, uncertainties và hashtags phải là mảng');
}
return [{ json: {
  title: String(draft.title).trim(), body: String(draft.body).trim(), pillar: draft.pillar,
  claims: draft.claims, uncertainties: draft.uncertainties, safety_note: String(draft.safety_note),
  hashtags: draft.hashtags, source_url: String(draft.source_url).trim(), status: 'needs_review', approved_at: null, approved_by: null, approval_required: true, idempotency_key: `draft:${String(draft.source_url).trim()}`
} }];

const item = $json;
if (item.approved_at || item.approved_by) {
  throw new Error('Intake không được nhận bản nháp đã approved; approval phải do reviewer ghi vào state store.');
}
const quote = (value) => `'${String(value ?? '').replaceAll("'", "''")}'`;
const jsonValue = (value) => quote(JSON.stringify(value ?? []));
const sourceUrl = String(item.source_url).trim();
let sourceName = 'unknown';
try { sourceName = new URL(sourceUrl).hostname; } catch (_) {}
const sql = `WITH source_upsert AS (
  INSERT INTO source_items(source_name, guid, url, url_hash, title, raw_excerpt, content_hash, status)
  VALUES (${quote(sourceName)}, ${quote(sourceUrl)}, ${quote(sourceUrl)}, md5(${quote(sourceUrl)}), ${quote(item.title)}, ${quote(item.body)}, md5(${quote(item.body)}), 'eligible')
  ON CONFLICT (url_hash) DO UPDATE SET last_seen_at = now(), title = EXCLUDED.title, raw_excerpt = EXCLUDED.raw_excerpt
  RETURNING id
), source_row AS (
  SELECT id FROM source_upsert
  UNION ALL SELECT id FROM source_items WHERE url_hash = md5(${quote(sourceUrl)}) LIMIT 1
), draft_insert AS (
  INSERT INTO content_drafts(source_item_id, pillar, title, body, claims_json, uncertainties_json, hashtags_json, safety_note, source_url, model_name, prompt_version, status)
  SELECT id, ${quote(item.pillar)}, ${quote(item.title)}, ${quote(item.body)}, ${jsonValue(item.claims)}, ${jsonValue(item.uncertainties)}, ${jsonValue(item.hashtags)}, ${quote(item.safety_note)}, ${quote(sourceUrl)}, 'gemini', 'content-pack.v1', 'needs_review'
  FROM source_row
  ON CONFLICT DO NOTHING
  RETURNING id, title, body, source_url, pillar, status
), audit_insert AS (
  INSERT INTO audit_events(entity_type, entity_id, event_type, actor_type, actor_id, payload_json)
  SELECT 'content_draft', id, 'draft_created', 'ai', 'gemini', jsonb_build_object('source_url', source_url, 'pillar', pillar)
  FROM draft_insert
)
SELECT id AS draft_id, title, body, source_url, pillar, status FROM draft_insert;`;
return [{ json: { ...item, state_operation: 'upsert_source_and_draft', state_sql: sql, draft_status: 'needs_review', provider_publish_blocked: true, next_step: 'human_review' } }];
